begin;
create function public.configurar_site(p_oficina uuid,p_dados jsonb) returns void language plpgsql security definer set search_path='' as $$
begin perform private.exigir_gestao(p_oficina,'website');
 if coalesce(p_dados->>'identificador_url','')!~'^[a-z0-9][a-z0-9-]{2,60}[a-z0-9]$' or length(trim(coalesce(p_dados->>'titulo',''))) not between 2 and 120 or length(coalesce(p_dados->>'descricao',''))>3000 then raise exception 'Confira o endereço, título e descrição.' using errcode='22023';end if;
 insert into public.sites_oficina(oficina_id,identificador_url,titulo,descricao,publicado,portal_habilitado,pedidos_pecas_habilitados)
 values(p_oficina,p_dados->>'identificador_url',trim(p_dados->>'titulo'),p_dados->>'descricao',coalesce((p_dados->>'publicado')::boolean,false),coalesce((p_dados->>'portal_habilitado')::boolean,false),coalesce((p_dados->>'pedidos_pecas_habilitados')::boolean,false))
 on conflict(oficina_id) do update set identificador_url=excluded.identificador_url,titulo=excluded.titulo,descricao=excluded.descricao,publicado=excluded.publicado,portal_habilitado=excluded.portal_habilitado,pedidos_pecas_habilitados=excluded.pedidos_pecas_habilitados;
end $$;
create function public.administrar_site(p_oficina uuid) returns jsonb language plpgsql security definer set search_path='' as $$
begin perform private.exigir_gestao(p_oficina,'website');return jsonb_build_object('site',(select to_jsonb(s) from public.sites_oficina s where oficina_id=p_oficina),'produtos',(select coalesce(jsonb_agg(to_jsonb(p)),'[]') from public.produtos_site p where oficina_id=p_oficina),'pedidos',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'situacao',p.situacao,'cliente',c.nome,'criado_em',p.criado_em,'observacoes',p.observacoes_cliente,'itens',(select jsonb_agg(jsonb_build_object('descricao',i.descricao,'quantidade',i.quantidade)) from public.itens_pedido_pecas i where i.pedido_id=p.id and i.oficina_id=p_oficina)) order by p.criado_em desc),'[]') from public.pedidos_pecas p join public.clientes c on c.id=p.cliente_id and c.oficina_id=p.oficina_id where p.oficina_id=p_oficina),'acessos',(select coalesce(jsonb_agg(jsonb_build_object('cliente_id',a.cliente_id,'nome',c.nome,'email',u.email,'usuario_id',a.usuario_id,'revogado_em',a.revogado_em)),'[]') from public.acessos_portal_cliente a join public.clientes c on c.id=a.cliente_id and c.oficina_id=a.oficina_id join auth.users u on u.id=a.usuario_id where a.oficina_id=p_oficina));end $$;
create function public.definir_acesso_portal(p_oficina uuid,p_cliente uuid,p_email text,p_revogar boolean default false) returns void language plpgsql security definer set search_path='' as $$
declare u uuid;begin perform private.exigir_gestao(p_oficina,'customer_portal');
 if p_revogar then update public.acessos_portal_cliente set revogado_em=now() where oficina_id=p_oficina and cliente_id=p_cliente and usuario_id in(select id from auth.users where lower(email)=lower(trim(p_email)));return;end if;
 select id into u from auth.users where lower(email)=lower(trim(p_email)) and email_confirmed_at is not null;if u is null then raise exception 'O cliente precisa criar e confirmar a conta com este e-mail antes da liberação.' using errcode='22023';end if;
 perform 1 from public.clientes where oficina_id=p_oficina and id=p_cliente and arquivado_em is null and lower(trim(email))=lower(trim(p_email));if not found then raise exception 'O e-mail deve corresponder ao cadastro do cliente.' using errcode='22023';end if;
 insert into public.acessos_portal_cliente(oficina_id,cliente_id,usuario_id,verificado_em,concedido_por) values(p_oficina,p_cliente,u,now(),auth.uid()) on conflict(oficina_id,cliente_id,usuario_id) do update set revogado_em=null,verificado_em=now(),concedido_por=auth.uid();
end $$;
create or replace function public.consultar_site_publicado(p_identificador_url text) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('oficina_id',s.oficina_id,'titulo',s.titulo,'descricao',s.descricao,'identificador_url',s.identificador_url,'identidade',w.identidade_documentos,'telefone',w.telefone_e164,'portal_habilitado',s.portal_habilitado and private.has_feature(s.oficina_id,'customer_portal'),'pedidos_habilitados',s.pedidos_pecas_habilitados and private.has_feature(s.oficina_id,'parts_requests'),'produtos',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'titulo',p.titulo,'descricao',p.descricao,'preco_centavos',p.preco_exibido_centavos)) from public.produtos_site p join public.itens_catalogo i on i.id=p.item_catalogo_id and i.oficina_id=p.oficina_id where p.oficina_id=s.oficina_id and p.visivel and i.arquivado_em is null),'[]')) from public.sites_oficina s join public.oficinas w on w.id=s.oficina_id where s.identificador_url=p_identificador_url and s.publicado and private.has_feature(s.oficina_id,'website');
$$;
create or replace function public.consultar_minhas_ordens_servico(p_oficina uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',w.id,'numero',w.numero,'situacao',w.situacao,'veiculo',jsonb_build_object('placa',w.dados_veiculo->>'placa','modelo',w.dados_veiculo->>'modelo'),'entrega_prevista_em',w.entrega_prevista_em,'resumo',w.resumo_cliente,'recebido_em',w.recebido_em,'entregue_em',w.entregue_em) order by w.criado_em desc),'[]') from public.ordens_servico w where w.oficina_id=p_oficina and private.has_portal_access(w.oficina_id,w.cliente_id);
$$;
create function public.consultar_meu_portal(p_oficina uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('clientes',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'nome',c.nome)) from public.clientes c where c.oficina_id=p_oficina and private.has_portal_access(c.oficina_id,c.id)),'[]'),'ordens',public.consultar_minhas_ordens_servico(p_oficina),'pedidos',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'situacao',p.situacao,'criado_em',p.criado_em,'itens',(select jsonb_agg(jsonb_build_object('descricao',i.descricao,'quantidade',i.quantidade)) from public.itens_pedido_pecas i where i.pedido_id=p.id and i.oficina_id=p_oficina))) from public.pedidos_pecas p where p.oficina_id=p_oficina and private.has_portal_access(p.oficina_id,p.cliente_id)),'[]'));
$$;
create function public.publicar_produto_site(p_oficina uuid,p_item uuid,p_visivel boolean) returns void language plpgsql security definer set search_path='' as $$
begin perform private.exigir_gestao(p_oficina,'website');
 insert into public.produtos_site(oficina_id,item_catalogo_id,titulo,descricao,visivel,preco_exibido_centavos) select p_oficina,id,descricao,descricao,p_visivel,preco_padrao_centavos from public.itens_catalogo where oficina_id=p_oficina and id=p_item and tipo='part' and arquivado_em is null on conflict(oficina_id,item_catalogo_id) do update set visivel=excluded.visivel,titulo=excluded.titulo,descricao=excluded.descricao,preco_exibido_centavos=excluded.preco_exibido_centavos;
 if not found then raise exception 'Peça ativa não encontrada.' using errcode='22023';end if;end $$;
create function public.atualizar_pedido_site(p_oficina uuid,p_pedido uuid,p_situacao text) returns void language plpgsql security definer set search_path='' as $$
begin perform private.exigir_gestao(p_oficina,'parts_requests');if p_situacao not in('reviewing','quoted','confirmed','ready','fulfilled','cancelled') then raise exception 'Situação inválida.' using errcode='22023';end if;update public.pedidos_pecas set situacao=p_situacao where oficina_id=p_oficina and id=p_pedido;if not found then raise exception 'Pedido não encontrado.' using errcode='22023';end if;end $$;
do $$declare f record;begin for f in select p.oid::regprocedure assinatura from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('configurar_site','administrar_site','definir_acesso_portal','consultar_meu_portal','publicar_produto_site','atualizar_pedido_site') loop execute format('revoke all on function %s from public,anon,authenticated',f.assinatura);execute format('grant execute on function %s to authenticated',f.assinatura);end loop;end $$;
notify pgrst,'reload schema';commit;
